theme_settings.custom-css:
/*
 * Leap registration-system recovery — 2026-07-13
 * Scope: native Uplifter registration, account, and checkout surfaces only.
 * Custom CMS content and site assistants are intentionally outside every selector.
 */

/* Keep the legacy Uplifter list behind the custom Registration CMS guide. */
html body #registration-list-view {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  min-height: 0 !important;
  overflow: hidden !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* Existing registration and invoice data-display rules retained from pre-regression CSS. */
.leap-registration-note {
  margin: 0 0 18px;
  padding: 14px 18px;
  border: 1px solid #d4e9f3;
  border-radius: 10px;
  background: #eef7fb;
  color: #2c5063;
  font-size: 0.95rem;
  line-height: 1.55;
}

.leap-registration-note strong { color: #1e2a32; }
.leap-registration-note a { color: #005a7a; font-weight: 700; }
.leap-program-hidden,
.leap-camp-hidden { display: none !important; }

#registration-list-view table.prodListItems tbody td:nth-child(2) {
  min-width: 190px;
  text-align: right;
}

#registration-list-view table.prodListItems .leap-fee-total {
  display: block;
  color: #1e2a32;
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1.15;
}

#registration-list-view table.prodListItems .leap-fee-monthly {
  display: block;
  margin-top: 6px;
  color: #005a7a;
  font-size: 0.88rem;
  font-weight: 600;
  line-height: 1.35;
}

#registration-list-view table.prodListItems input.btnAction:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

#registration-list-view table.prodListItems tbody.leap-group-start tr td,
#registration-list-view table.prodListItems tbody.leap-group-single tr td {
  padding-top: 18px;
}

#registration-list-view table.prodListItems tbody.leap-group-start:not(:first-of-type) tr td,
#registration-list-view table.prodListItems tbody.leap-group-single:not(:first-of-type) tr td {
  border-top: 2px solid #d8ecf4;
}

#registration-list-view table.prodListItems tbody.leap-group-middle tr td,
#registration-list-view table.prodListItems tbody.leap-group-end tr td {
  border-top: 0;
  padding-top: 10px;
}

#registration-list-view table.prodListItems .itemTitle { font-weight: 700; }

#registration-list-view table.prodListItems .leap-subsection-title {
  display: block;
  margin: 0 0 10px;
  color: #00447d;
  font-size: 0.82rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

#registration-list-view table.prodListItems tbody.leap-group-middle .itemTitle,
#registration-list-view table.prodListItems tbody.leap-group-end .itemTitle {
  font-weight: 600;
}

#checkout .finalTotalTable .grandTotal th,
#checkout .finalTotalTable .grandTotal .orderTotal span { color: #00447d; }

#checkout .finalTotalTable .grandTotal .orderTotal span {
  font-size: 2rem;
  font-weight: 700;
}

#checkout .finalTotalTable td .fullWidthField::after {
